def apply(self,action,dt):
    assert abs(dt-.02)<1e-9
    # Original source checks four outer 5 ms ticks. Each now contains
    # five actual motor/solver updates; preserve that check without changing
    # the immutable controller or hiding the environment's real update count.
    if self.ctx._pd_substeps is not None:
        if self.ctx._pd_substeps!=20:raise RuntimeError('H requires 20 local motor updates per action')
        self.ctx._pd_substeps=4
    self.ctx._pre_physics_step(action)
    return dict(leg_pos_rad=self.ctx.target,wheel_vel_rad_s=self.ctx.wheel_target)
